style.css:
@-moz-document domain("google.com") {
/* Logo plateado con brillo */
  svg[aria-label="Google"] path {
    fill: #c0c0c0 !important; /* plateado */
    filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.6));
  }

  /* Barra de búsqueda personalizada */
  input.gLFyf {
    background-color: #0d47a1 !important; /* azul oscuro */
    color: white !important; /* texto blanco */
    border-radius: 25px !important; /* esquinas redondeadas */
    border: 1px solid rgba(255, 255, 255, 0.3) !important; /* borde suave */
    padding: 8px 16px !important;
  }

  /* Color del texto sugerido */
  .aajZCb {
    background-color: rgba(13, 71, 161, 0.9) !important; /* azul translúcido */
    color: white !important;
  }

  /* Fondo general de la página */
  body {
    background-color: #0b0f1c !important; /* azul muy oscuro elegante */
  }
}
